87	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
88	    @Override
89	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
90	        Collection<Owner> owners;
91	        if (lastName != null) {
92	            owners = this.clinicService.findOwnerByLastName(lastName);
93	        } else {
94	            owners = this.clinicService.findAllOwners();
95	        }
96	        if (owners.isEmpty()) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        Map<String, Integer> householdSizes = householdSizes();
100	        List<OwnerDto> ownerDtos = new java.util.ArrayList<>();
101	        for (Owner owner : owners) {
102	            OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
103	            applyMembership(ownerDto, owner, householdSizes);
104	            ownerDtos.add(ownerDto);
105	        }
106	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
107	    }
