122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
125	        HttpHeaders headers = new HttpHeaders();
126	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
127	        String address = normalizeAddress(owner.getAddress());
128	        if (address.isEmpty()) {
129	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
130	        }
131	        owner.setAddress(address);
132	        String telephone = toE164(owner.getTelephone());
133	        if (telephone == null) {
134	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
135	        }
136	        owner.setTelephone(telephone);
137	        if (owner.getEmail() != null) {
138	            String email = normalizeEmail(owner.getEmail());
139	            if (email == null) {
140	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
141	            }
142	            owner.setEmail(email);
143	        }
144	        if (owner.getPostcode() != null && !isValidPostcode(owner.getPostcode(), owner.getCity())) {
145	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
146	        }
147	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
148	        if (effectiveRegistrationDate == null) {
149	            effectiveRegistrationDate = LocalDate.now();
150	        }
151	        else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
152	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
153	        }
154	        LocalDate registrationDate = toBusinessDay(effectiveRegistrationDate);
155	        owner.setRegistrationDate(registrationDate);
156	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
157	            return new ResponseEntity<>(HttpStatus.CONFLICT);
158	        }
159	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
160	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
161	        }
162	        // The householdId is deterministic: the first twelve hex characters of SHA-256 over
163	        // '<normalizedLastName>|<postcode>'. Owners sharing a last name and postcode therefore
164	        // share the household automatically. An owner without a postcode has no household.
165	        boolean declaredHouseholdMember = false;
166	        if (owner.getPostcode() != null) {
167	            String householdId = householdId(householdKey(owner.getLastName()), owner.getPostcode());
168	            owner.setHouseholdId(householdId);
169	            // Because the household is now keyed on (lastName, postcode), a second owner in the
170	            // same household is a household duplicate: rejected with 409 unless it opts in with
171	            // 'sharesHousehold', in which case it is created as a declared household member.
172	            boolean householdOccupied = false;
173	            for (Owner existing : this.clinicService.findAllOwners()) {
174	                if (householdId.equals(computeHouseholdId(existing))) {
175	                    householdOccupied = true;
176	                    break;
177	                }
178	            }
179	            if (householdOccupied) {
180	                if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
181	                    return new ResponseEntity<>(HttpStatus.CONFLICT);
182	                }
183	                declaredHouseholdMember = true;
184	            }
185	        }
186	        // Consolidated duplicate detection: reject only when the whole identityKey
187	        // (normalized telephone | email | householdId) matches an existing owner's.
188	        String identityKey = identityKey(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
189	        for (Owner existing : this.clinicService.findAllOwners()) {
190	            if (identityKey.equals(identityKey(toE164(existing.getTelephone()),
191	                emailForKey(existing.getEmail()), existing.getHouseholdId()))) {
192	                return new ResponseEntity<>(HttpStatus.CONFLICT);
193	            }
194	        }
195	        // Soft-match: the owner is not a hard (identityKey) duplicate, but if it shares an
196	        // existing owner's last name and postcode while having a different normalized
197	        // telephone it is still created and flagged as a possible duplicate of that owner. A
198	        // declared household member, however, is not a suspected duplicate, so it is never flagged.
199	        if (declaredHouseholdMember) {
200	            owner.setPossibleDuplicate(false);
201	        }
202	        else {
203	            applyPossibleDuplicate(owner);
204	        }
205	        owner.setCustomerCode(customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName()));
206	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
207	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
208	        this.clinicService.saveOwner(owner);
209	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
210	        applyMembership(ownerDto, owner);
211	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
212	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
213	            ownerDto.getMembershipLevel());
214	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
215	        headers.setLocation(UriComponentsBuilder.newInstance()
216	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
217	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
218	    }
