313	    /**
314	     * The maximum number of owners permitted per city. Owner creation is rejected once the
315	     * owner's city already contains this many owners.
316	     */
317	    private static final int MAX_OWNERS_PER_CITY = 50;
318	
319	    /**
320	     * Counts how many existing owners live in the given city, compared case-insensitively.
321	     * This is evaluated before the new owner is persisted, so the owner being created is not
322	     * included in the count.
323	     *
324	     * @param city the new owner's city
325	     * @return the number of existing owners in that city
326	     */
327	    private int countOwnersInCity(String city) {
328	        int count = 0;
329	        for (Owner existing : this.clinicService.findAllOwners()) {
330	            if (city.equalsIgnoreCase(existing.getCity())) {
331	                count++;
332	            }
333	        }
334	        return count;
335	    }
336	
337	    /**
338	     * The maximum number of owners that may be created in a single business day. Owner
339	     * creation is rejected once this many owners already fall on the new owner's adjusted
340	     * business day {@code registrationDate}.
341	     */
342	    private static final int MAX_OWNERS_PER_DAY = 100;
343	
344	    /**
345	     * Rolls a date forward to the next business day: a Saturday or Sunday is moved forward
346	     * to the following Monday, while a weekday is returned unchanged.
347	     *
348	     * @param date the date to adjust
349	     * @return the same date if it is a weekday, otherwise the following Monday
350	     */
351	    private LocalDate toBusinessDay(LocalDate date) {
352	        DayOfWeek dayOfWeek = date.getDayOfWeek();
353	        if (dayOfWeek == DayOfWeek.SATURDAY) {
354	            return date.plusDays(2);
355	        }
356	        if (dayOfWeek == DayOfWeek.SUNDAY) {
357	            return date.plusDays(1);
358	        }
359	        return date;
360	    }
361	
362	    /**
363	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
364	     * registrationDate} rolls forward to the same business day. This is evaluated before the
365	     * new owner is persisted, so the owner being created is not included in the count.
366	     *
367	     * @param businessDay the adjusted business day to count against
368	     * @return the number of existing owners registered on that business day
369	     */
370	    private int countOwnersRegisteredOn(LocalDate businessDay) {
371	        int count = 0;
372	        for (Owner existing : this.clinicService.findAllOwners()) {
373	            LocalDate existingDate = existing.getRegistrationDate();
374	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
375	                count++;
376	            }
377	        }
378	        return count;
379	    }
380	
381	    /**
382	     * The number of owners that may be created on a single business day before a bulk-signup
383	     * warning is raised. Once more than this many owners already fall on the current business
384	     * day, {@code bulkSignupWarning} is reported as {@code true} in the owner response.
385	     */
386	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
387	
388	    /**
389	     * Reports whether an unusually high number of owners have been created for today's business
390	     * day, i.e. whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already fall on
391	     * the business day that {@code LocalDate.now()} rolls forward to.
392	     *
393	     * @return {@code true} once more than 80 owners have been created today, otherwise {@code false}
394	     */
395	    private boolean isBulkSignupDay() {
396	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > BULK_SIGNUP_WARNING_THRESHOLD;
397	    }
398	
399	    /**
400	     * Builds the customer code for a newly created owner, formatted
401	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the canonical region
402	     * {@link OwnerLocality#forPostcodeOrUnknown derived from the postcode} (or
403	     * {@code "UNKNOWN"} when the postcode resolves no region) and {@code HASH8} is the
404	     * first eight upper-case hex characters of the SHA-256 digest of
405	     * {@code normalizedTelephone + lastName}. The code carries no sequence number, so it is
406	     * stable for a given telephone and last name rather than dependent on creation order.
407	     *
408	     * @param postcode            the owner's postcode (may be {@code null})
409	     * @param normalizedTelephone the owner's normalized E.164 telephone
410	     * @param lastName            the owner's last name
411	     * @return the assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
412	     */
413	    private static String customerCode(String postcode, String normalizedTelephone, String lastName) {
414	        String region = org.springframework.samples.petclinic.mapper.OwnerLocality.forPostcodeOrUnknown(postcode);
415	        return region + "-" + sha256Hex8(normalizedTelephone + lastName);
416	    }
417	
418	    /**
419	     * Returns the first eight upper-case hex characters of the SHA-256 digest of the UTF-8
420	     * bytes of {@code source} — the {@code HASH8} component of an owner's customer code.
421	     *
422	     * @param source the string to hash
423	     * @return the first eight upper-case hex characters of {@code SHA-256(source)}
424	     */
425	    private static String sha256Hex8(String source) {
426	        try {
427	            byte[] digest = MessageDigest.getInstance("SHA-256")
428	                .digest(source.getBytes(StandardCharsets.UTF_8));
429	            StringBuilder hex = new StringBuilder(digest.length * 2);
430	            for (byte b : digest) {
431	                hex.append(String.format("%02x", b));
432	            }
433	            return hex.substring(0, 8).toUpperCase();
434	        } catch (NoSuchAlgorithmException e) {
435	            throw new IllegalStateException("SHA-256 not available", e);
436	        }
437	    }
438	
439	    /**
440	     * Builds the membership number for a newly created owner, formatted
441	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
442	     * customer code and {@code YY} is the last two digits of the owner's registration
443	     * date year, zero-padded to two digits.
444	     *
445	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
446	     * @param registrationDate the owner's registration date
447	     * @return the assigned membership number (e.g. {@code 'NSW-1A2B3C4D-M26'})
448	     */
449	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
450	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
451	    }
452	
453	    /**
454	     * Counts how many existing owners share the given first and last name, compared
455	     * case-insensitively. This is evaluated before the new owner is persisted, so the
456	     * owner being created is not included in the count.
457	     *
458	     * @param firstName the new owner's first name
459	     * @param lastName  the new owner's last name
460	     * @return the number of existing owners with the same first and last name
461	     */
462	    private int countNamesakes(String firstName, String lastName) {
463	        int count = 0;
464	        for (Owner existing : this.clinicService.findAllOwners()) {
465	            if (firstName.equalsIgnoreCase(existing.getFirstName())
466	                && lastName.equalsIgnoreCase(existing.getLastName())) {
467	                count++;
468	            }
469	        }
470	        return count;
471	    }
472	
473	    /**
474	     * Canonical expansions applied to common street-type abbreviations during address
475	     * normalization. Keys and values are upper-cased so the lookup runs after the address
476	     * has itself been upper-cased.
477	     */
478	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
479	        "ST", "STREET",
480	        "RD", "ROAD",
481	        "AVE", "AVENUE");
482	
483	    /**
484	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
485	     * every run of internal whitespace is collapsed to a single space, the result is
486	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
487	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
488	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
489	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
490	     * returned and compared for household duplicates; an address that is blank once
491	     * normalized fails the required-field check.
492	     *
493	     * @param address the raw address value supplied by the client
494	     * @return the normalized address (empty string when {@code address} is null or blank)
495	     */
496	    private static String normalizeAddress(String address) {
497	        if (address == null) {
498	            return "";
499	        }
500	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
501	        if (collapsed.isEmpty()) {
502	            return "";
503	        }
504	        StringBuilder normalized = new StringBuilder(collapsed.length());
505	        for (String token : collapsed.split(" ")) {
506	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
507	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
508	            if (normalized.length() > 0) {
509	                normalized.append(' ');
510	            }
511	            normalized.append(expanded != null ? expanded : token);
512	        }
513	        return normalized.toString();
514	    }
515	
516	    /**
517	     * Normalizes a last name or address for household-duplicate comparison: leading and
518	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
519	     * single space and the result is lower-cased. Two owners are considered to share a
520	     * household when both their last names and addresses produce the same key.
521	     *
522	     * @param value the raw last name or address value
523	     * @return the normalized comparison key (empty string when {@code value} is null)
524	     */
525	    private static String householdKey(String value) {
526	        if (value == null) {
527	            return "";
528	        }
529	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
530	    }
531	
532	    /**
533	     * Derives the stable shared household identifier for the given normalized last name key
534	     * and postcode. The identifier is deterministic — the same household (same
535	     * {@link #householdKey normalized} last name and postcode) always maps to the same
536	     * value — so every owner in a household is assigned an identical id. It is the
537	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
538	     * '<lastNameKey>|<postcode>'}.
539	     *
540	     * @param lastNameKey the normalized last name key
541	     * @param postcode    the owner's postcode
542	     * @return the shared household identifier
543	     */
544	    private static String householdId(String lastNameKey, String postcode) {
545	        String source = lastNameKey + "|" + postcode;
546	        try {
547	            byte[] digest = MessageDigest.getInstance("SHA-256")
548	                .digest(source.getBytes(StandardCharsets.UTF_8));
549	            StringBuilder hex = new StringBuilder(digest.length * 2);
550	            for (byte b : digest) {
551	                hex.append(String.format("%02x", b));
552	            }
553	            return hex.substring(0, 12).toUpperCase();
554	        } catch (NoSuchAlgorithmException e) {
555	            throw new IllegalStateException("SHA-256 not available", e);
556	        }
557	    }
558	
559	    /**
560	     * Computes the deterministic {@link #householdId household id} an existing owner belongs to,
561	     * derived from its {@link #householdKey normalized} last name and its postcode. Returns
562	     * {@code null} when the owner has no postcode (such an owner has no household), so it never
563	     * collides with a computed household id.
564	     *
565	     * @param owner the existing owner
566	     * @return the owner's household id, or {@code null} when it has no postcode
567	     */
568	    private static String computeHouseholdId(Owner owner) {
569	        if (owner.getPostcode() == null) {
570	            return null;
571	        }
572	        return householdId(householdKey(owner.getLastName()), owner.getPostcode());
573	    }
574	
575	    /**
576	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
577	     * dto, sizing the owner's household from all owners so the household-of-three-or-more
578	     * factor is scored correctly. Use {@link #applyMembership(OwnerDto, Owner, Map)} instead
579	     * when mapping a collection to size every household from a single scan.
580	     *
581	     * @param ownerDto the dto to populate
582	     * @param owner    the owner being mapped
583	     */
584	    private void applyMembership(OwnerDto ownerDto, Owner owner) {
585	        applyMembership(ownerDto, owner, householdSizes());
586	    }
587	
588	    /**
589	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
590	     * dto using a pre-computed map of household id to member count.
591	     *
592	     * @param ownerDto       the dto to populate
593	     * @param owner          the owner being mapped
594	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
595	     */
596	    private void applyMembership(OwnerDto ownerDto, Owner owner, Map<String, Integer> householdSizes) {
597	        int householdSize = owner.getHouseholdId() == null ? 1
598	            : householdSizes.getOrDefault(owner.getHouseholdId(), 1);
599	        int points = MembershipPoints.points(owner, householdSize);
600	        ownerDto.setMembershipPoints(points);
601	        ownerDto.setMembershipLevel(MembershipPoints.level(points));
602	    }
603	
604	    /**
605	     * Counts how many owners belong to each household, keyed by household id. Owners without a
606	     * household id (no postcode) are excluded — such an owner is its own single-member household.
607	     *
608	     * @return a map from household id to the number of owners sharing it
609	     */
610	    private Map<String, Integer> householdSizes() {
611	        Map<String, Integer> sizes = new java.util.HashMap<>();
612	        for (Owner existing : this.clinicService.findAllOwners()) {
613	            String householdId = existing.getHouseholdId();
614	            if (householdId != null) {
615	                sizes.merge(householdId, 1, Integer::sum);
616	            }
617	        }
618	        return sizes;
619	    }
620	
621	    /**
622	     * Applies soft-match (possible-duplicate) detection to a new owner that has already
623	     * cleared hard {@code identityKey} duplicate rejection. The owner is flagged as a
624	     * possible duplicate when an existing owner shares its last name (compared
625	     * case-insensitively with collapsed whitespace) and its postcode while having a
626	     * different normalized telephone; {@code possibleDuplicateOf} is then set to that
627	     * existing owner's id. When several existing owners match, the one with the lowest id
628	     * is chosen so the result is deterministic. When no such owner exists — or the new
629	     * owner has no postcode to compare — {@code possibleDuplicate} is set to {@code false}
630	     * and no matching id is recorded.
631	     *
632	     * @param owner the new owner, already normalized (E.164 telephone, validated postcode)
633	     */
634	    private void applyPossibleDuplicate(Owner owner) {
635	        owner.setPossibleDuplicate(false);
636	        if (owner.getPostcode() == null) {
637	            return;
638	        }
639	        String lastNameKey = householdKey(owner.getLastName());
640	        Owner match = null;
641	        for (Owner existing : this.clinicService.findAllOwners()) {
642	            if (lastNameKey.equals(householdKey(existing.getLastName()))
643	                && owner.getPostcode().equals(existing.getPostcode())
644	                && !owner.getTelephone().equals(toE164(existing.getTelephone()))) {
645	                if (match == null || (existing.getId() != null
646	                    && existing.getId() < match.getId())) {
647	                    match = existing;
648	                }
649	            }
650	        }
651	        if (match != null) {
652	            owner.setPossibleDuplicate(true);
653	            owner.setPossibleDuplicateOf(match.getId());
654	        }
655	    }
656	
657	    /**
658	     * Builds the derived duplicate-detection identity key from an owner's normalized
659	     * telephone, email and household id, formatted {@code
660	     * '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Two owners are
661	     * duplicates only when their whole identity keys are equal; because the telephone is
662	     * part of the key, members of the same household with different telephones produce
663	     * different keys and are both allowed.
664	     *
665	     * @param normalizedTelephone the E.164 telephone (may be {@code null})
666	     * @param email               the normalized (lower-cased) email, or {@code null} when absent
667	     * @param householdId         the shared household id, or {@code null} when the owner is not in a household
668	     * @return the identity key string
669	     */
670	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
671	        return (normalizedTelephone == null ? "" : normalizedTelephone)
672	            + "|" + (email == null ? "" : email)
673	            + "|" + (householdId == null ? "" : householdId);
674	    }
675	
676	    /**
677	     * Normalizes an existing owner's stored email for identity-key comparison: trimmed and
678	     * lower-cased, mirroring {@link #normalizeEmail} without re-validating syntax. Returns
679	     * {@code null} when the owner has no email.
680	     *
681	     * @param email the existing owner's stored email (may be {@code null})
682	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is null
683	     */
684	    private static String emailForKey(String email) {
685	        return email == null ? null : email.trim().toLowerCase();
686	    }
687	
688	    /**
689	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
690	     * and brackets are stripped. When the number already carries a leading {@code '+'}
691	     * and country code these are kept; a number written in national trunk form (a leading
692	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
693	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
694	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
695	     * after the {@code '+'}, and its national-number length must be valid for the detected
696	     * country code (see {@link #hasValidNationalLength}).
697	     *
698	     * @param telephone the raw telephone value supplied by the client
699	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
700	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
701	     */
702	    private static String toE164(String telephone) {
703	        if (telephone == null) {
704	            return null;
705	        }
706	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
707	        String digits;
708	        if (cleaned.startsWith("+")) {
709	            digits = cleaned.substring(1);
710	        } else if (cleaned.startsWith("0")) {
711	            digits = "61" + cleaned.substring(1);
712	        } else {
713	            digits = "1" + cleaned;
714	        }
715	        if (!digits.matches("[0-9]{8,15}")) {
716	            return null;
717	        }
718	        if (!hasValidNationalLength(digits)) {
719	            return null;
720	        }
721	        return "+" + digits;
722	    }
723	
724	    /**
725	     * Validates the national-number length of an E.164 digit string against its country
726	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
727	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
728	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
729	     *
730	     * @param digits the E.164 digits (without the leading {@code '+'})
731	     * @return {@code true} when the national-number length is valid for the country code
732	     */
733	    private static boolean hasValidNationalLength(String digits) {
734	        if (digits.startsWith("61")) {
735	            return digits.length() - 2 == 9;
736	        }
737	        if (digits.startsWith("1")) {
738	            return digits.length() - 1 == 10;
739	        }
740	        return true;
741	    }
742	
743	    /**
744	     * Inclusive 4-digit postcode ranges permitted for each canonical region: NSW 2000-2099,
745	     * VIC 3000-3099 and QLD 4000-4099. A region absent from this table (e.g. the {@code
746	     * "UNKNOWN"} derived for a city with no known region) imposes no range restriction.
747	     */
748	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
749	        "NSW", new int[] {2000, 2099},
750	        "VIC", new int[] {3000, 3099},
751	        "QLD", new int[] {4000, 4099});
752	
753	    /**
754	     * Validates an owner's postcode for creation. A postcode is only ever validated when
755	     * present (an absent postcode is optional and accepted). When present it must be exactly
756	     * four digits and, for a city whose {@link OwnerLocality#forCity region} has a known
757	     * postcode range, must fall inside that inclusive range (NSW 2000-2099, VIC 3000-3099,
758	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
759	     *
760	     * @param postcode the supplied postcode (never {@code null} here)
761	     * @param city     the owner's city, used to derive the region
762	     * @return {@code true} when the postcode is valid for the city, {@code false} otherwise
763	     *         (signalling a 400 Bad Request)
764	     */
765	    private static boolean isValidPostcode(String postcode, String city) {
766	        if (!postcode.matches("[0-9]{4}")) {
767	            return false;
768	        }
769	        int[] range = REGION_POSTCODES.get(
770	            org.springframework.samples.petclinic.mapper.OwnerLocality.forCity(city));
771	        if (range == null) {
772	            return true;
773	        }
774	        int value = Integer.parseInt(postcode);
775	        return value >= range[0] && value <= range[1];
776	    }
777	
778	    /**
779	     * Disposable email domains that are not accepted for owner creation. An owner whose
780	     * email domain (compared case-insensitively) is in this set is rejected with a 400
781	     * Bad Request.
782	     */
783	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
784	        "mailinator.com", "tempmail.com", "guerrillamail.com");
785	
786	    /**
787	     * Normalizes an owner email for creation. A present email must be a syntactically
788	     * valid address whose domain is not on the disposable-domain blocklist ({@link
789	     * #DISPOSABLE_EMAIL_DOMAINS}); the returned value is lower-cased.
790	     *
791	     * @param email the raw email value supplied by the client (never {@code null} here)
792	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
793	     *         address or its domain is a disposable domain (signalling a 400 Bad Request)
794	     */
795	    private static String normalizeEmail(String email) {
796	        String trimmed = email.trim();
797	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
798	            return null;
799	        }
800	        String normalized = trimmed.toLowerCase();
801	        String domain = normalized.substring(normalized.indexOf('@') + 1);
802	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
803	            return null;
804	        }
805	        return normalized;
806	    }
807	}
